{"name":"ucsi_unregister_altmodes","qualified_name":"workspace-linux.drivers.usb.typec.ucsi.ucsi.ucsi_unregister_altmodes","label":"Function","file_path":"/workspace/linux/drivers/usb/typec/ucsi/ucsi.c","start_line":639,"end_line":673,"source":"static void ucsi_unregister_altmodes(struct ucsi_connector *con, u8 recipient)
{
	const struct typec_altmode *pdev;
	struct typec_altmode **adev;
	int i = 0;

	switch (recipient) {
	case UCSI_RECIPIENT_CON:
		adev = con->port_altmode;
		break;
	case UCSI_RECIPIENT_SOP:
		adev = con->partner_altmode;
		break;
	case UCSI_RECIPIENT_SOP_P:
		adev = con->plug_altmode;
		break;
	default:
		return;
	}

	while (adev[i]) {
		if (recipient == UCSI_RECIPIENT_SOP) {
			pdev = typec_altmode_get_partner(adev[i]);

			if (adev[i]->svid == USB_TYPEC_DP_SID ||
			    (adev[i]->svid == USB_TYPEC_NVIDIA_VLINK_SID &&
			     adev[i]->vdo != USB_TYPEC_NVIDIA_VLINK_DBG_VDO))
				ucsi_displayport_remove_partner((void *)pdev);
			else if (adev[i]->svid == USB_TYPEC_TBT_SID)
				ucsi_thunderbolt_remove_partner((void *)pdev);
		}
		typec_unregister_altmode(adev[i]);
		adev[i++] = NULL;
	}
}
